    {
      "path": "packages/dsh-ssh/cordis.patch.yml",
      "content": "# dsh-ssh bundle patch: inserts the dual-face plugin row into the web\n# profile roster. Applied as a profile bundle layer (the `dsh.bundle.patch`\n# manifest field) over dsh-base; activate with\n# `dsh plugin --profile <name> add link:~/code/dsh-web-ui/packages/dsh-ssh`.\n#\n# The row is a bare plugin by package name: the node half (exports \".\") runs\n# in the host process (SSH engine, /api/dsh-ssh routes, agent tools), and the\n# `dsh.client` declaration in package.json makes the browser half\n# (exports \"./client\", served at /plugins/<id>/client.js) load in the web GUI.\n- insert:\n    - id: ssh\n      name: '@linxin666/dsh-ssh'\n"
    },
    {
      "path": "packages/dsh-ssh/src/index.ts",
      "content": "/**\n * dsh-ssh — host half. Mounts the SSH engine (persistent ssh2 connection\n * pool, exec / PTY shell / SFTP / tunnels / cluster), the /api/dsh-ssh route\n * family plus the terminal WebSocket upgrade, the agent tools (ssh_list,\n * ssh_exec, ssh_upload, ssh_download, ssh_tunnel, ssh_cluster), and a\n * system-prompt announcement. The browser half (./client) renders the host\n * manager and web terminal. Everything rides official NPM SDK packages —\n * no dsh source changes.\n */\n\nimport type { Context, Fiber } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport type {} from '@deepseek-ai/dsh-host-webserver'\nimport type {} from '@deepseek-ai/dsh-system-prompt'\nimport type {} from '@deepseek-ai/dsh-tools'\nimport { SshEngine } from './engine.ts'\nimport { DEFAULT_CONNECT_TIMEOUT_MS } from './engine/connection-pool.ts'\nimport { makeRoutes } from './routes.ts'\nimport { HostStore } from './store.ts'\nimport { sshClusterTool, sshDownloadTool, sshExecTool, sshListTool, sshTunnelTool, sshUploadTool } from './tools.ts'\nimport { mountOnce } from './mount-once.ts'\nimport { PLUGIN_TOOL_SECTION_ORDERS, visibleToolText } from './tool-surface.ts'\n\n/** Stable cordis plugin name. */\nexport const name = 'ssh'\n\n/** Services required before the SSH surfaces can mount. */\nexport const inject = ['webServer', 'tools', 'systemPrompt']\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Events {\n    /**\n     * Volatile config values were committed into the running instance without a\n     * remount (cordis-plugin-loader); dispatched to the owning fiber only.\n     * @param paths - the changed config paths, as key arrays.\n     * @mode emit\n     */\n    'loader/volatile-update'(paths: readonly (readonly string[])[]): void\n  }\n}\n\n/** Plugin config as a profile patch declares it, before schema resolution. */\nexport interface Config {\n  /**\n   * When true, a system-prompt section announces the SSH plugin to every agent\n   * (tools + host store). Off by default to keep prompts clean.\n   */\n  announceToAgent?: boolean\n  /** Master switch for the plugin (routes, tools, prompt section). */\n  enabled?: boolean\n  /**\n   * xterm `fontFamily` for the web terminal (issue #577). Empty (default)\n   * defers to the CSS chain: `--dsh-ssh-terminal-font`, then the official\n   * `--ds-font-family-code` token, then the built-in monospace stack. Set a\n   * Nerd Font stack here to render powerline/Nerd glyphs.\n   */\n  terminalFontFamily?: string\n  /**\n   * Ceiling for the whole pre-ready SSH sequence in milliseconds: TCP\n   * connect, key exchange and user authentication (default 30000). Raise it\n   * for hosts whose password authentication is slow (for example PAM / LDAP\n   * behind a distant directory service).\n   */\n  connectTimeoutMs?: number\n}\n\n/** The stable reference a `volatile()` config field resolves to; its owner updates it in place. */\ninterface ConfigRef<T> {\n  /** @returns the field's current value. */\n  get(): T\n}\n\n/** One resolved config field: a live reference, or a plain value from a hand-built context. */\ntype ConfigField<T> = ConfigRef<T> | T\n\n/** The config the Host hands to {@link apply} — the runtime face of {@link Config}. */\nexport interface ResolvedConfig {\n  announceToAgent?: ConfigField<boolean>\n  enabled?: ConfigField<boolean>\n  terminalFontFamily?: ConfigField<string>\n  connectTimeoutMs?: ConfigField<number>\n}\n\n/**\n * Plugin config schema. Under the 0.1.7 settings model this schema IS the\n * entry's settings page: the Host derives one form per profile entry from it\n * and serves it through the shared configuration forms. Every field is\n * `volatile()`, which is what puts it on that page and what lets an edit reach\n * a running instance without a remount: the loader commits the new value into\n * the field's reference and announces `loader/volatile-update` on this fiber.\n */\nexport const Config = z.object({\n  announceToAgent: z.boolean().default(false).volatile(),\n  enabled: z.boolean().default(true).volatile(),\n  terminalFontFamily: z.string().default('').volatile(),\n  connectTimeoutMs: z.number().step(1).min(1_000).max(600_000).default(DEFAULT_CONNECT_TIMEOUT_MS).volatile()\n    .description('TCP connect, SSH key exchange and user authentication timeout in milliseconds; raise it for hosts whose authentication is slow.'),\n})\n\n/** Schema defaults, re-read for hand-built test contexts (the loader applies them normally). */\nconst DEFAULT_ANNOUNCE = false\nconst DEFAULT_ENABLED = true\n\n/** Read one resolved config field, following the live reference the schema produces. */\nfunction readConfigField<T>(field: ConfigField<T> | undefined, fallback: T): T {\n  if (field === undefined) return fallback\n  if (typeof field === 'object' && field !== null && typeof (field as ConfigRef<T>).get === 'function') {\n    const value = (field as ConfigRef<T>).get()\n    return value === undefined ? fallback : value\n  }\n  return field as T\n}\n\n/**\n * The loader's own record of the profile entry this instance was activated\n * from, which carries the row's raw config — the user's own declaration, as\n * opposed to the schema defaults and the inherited bundle layers. Absent on a\n * host without the loader, which reads as \"the profile declares nothing\".\n */\ninterface LoaderEntry {\n  options?: { config?: unknown }\n}\n\n/** Raw config the profile declares for this entry, when the loader exposes it. */\nfunction profileConfig(ctx: Context): Record<string, unknown> | undefined {\n  const entry = (ctx.fiber as Fiber & { entry?: LoaderEntry }).entry\n  const config = entry?.options?.config\n  if (typeof config !== 'object' || config === null || Array.isArray(config)) return undefined\n  return config as Record<string, unknown>\n}\n\n/** Order of the announcement section within the shared tool-guidance band. */\nconst SECTION_ORDER = PLUGIN_TOOL_SECTION_ORDERS.ssh\n\n/** The six agent-tool names this plugin's announcement describes. */\nconst SSH_TOOL_NAMES = ['ssh_list', 'ssh_exec', 'ssh_upload', 'ssh_download', 'ssh_tunnel', 'ssh_cluster'] as const\n\n/** Model-facing announcement: plugin presence, capabilities, and limits. */\nexport const SSH_GUIDANCE = '本机已安装 dsh-ssh 插件（DSH 远程 SSH 运维）：侧边栏「SSH」入口；在 dsh-web 插件全家桶仓库（packages/dsh-ssh）统一维护。能力：主机配置存 $DSH_HOME/dsh-ssh.json（默认 ~/.dsh）（可从 ~/.ssh/config 导入）；持久连接池复用长连接（空闲 30 分钟自动断开）；ssh_list 列出主机、ssh_exec 执行远程命令、ssh_upload/ssh_download 传输文件、ssh_tunnel 本地端口转发（访问远程数据库/内网服务）、ssh_cluster 按 aliases/environment/tags 至少一种非空 selector 筛选后集群并发执行；支持密钥/密码/ssh-agent 认证、passphrase 密钥、ProxyJump 跳板机（别名或 [user@]host[:port] 地址）与 OpenSSH 语义的 ProxyCommand（跳过堡垒机客户端场景，只能由用户在 GUI 配置，agent 不可写）；Web 终端走 WebSocket。限制：主机操作由用户在 GUI 中配置后 agent 方可使用；密码以明文存在用户主目录私有文件（权限 0600）；命令输出原样返回、可能含敏感信息；断线重连可能重放非幂等命令；传输/执行消耗真实远程资源，先确认再操作。路径区分：本机（dsh host）上的文件与命令一律用本地工具（read / write / edit / bash），ssh_* 工具只针对远程主机上的路径。用户提到「SSH / 远程服务器 / 服务器操作 / 跳板机 / 隧道 / 部署 / 上传下载」时即指本插件，请据此协作。'\n\n/**\n * Mount the SSH engine, routes, tools, and announcement.\n * @param ctx - host plugin context carrying webServer/tools/systemPrompt.\n * @param config - resolved plugin config (schema defaults applied by the loader).\n */\nexport const apply = mountOnce('@linxin666/dsh-ssh', applyImpl)\n\nfunction applyImpl(ctx: Context, config?: ResolvedConfig): void {\n  const store = new HostStore()\n  const engine = new SshEngine(store, { connectTimeoutMs: readConfigField(config?.connectTimeoutMs, DEFAULT_CONNECT_TIMEOUT_MS) })\n  ctx.effect(() => () => { engine.dispose() }, 'dsh-ssh: engine')\n\n  const resolve = (): { announceToAgent: boolean; enabled: boolean } => {\n    let enabled = readConfigField(config?.enabled, DEFAULT_ENABLED)\n    // When dsh-ssh was seeded with enabled: false (e.g. from an aggregate profile\n    // line), but the profile's own entry config never set the switch AND the user\n    // already has active host records in dsh-ssh.json, keep the plugin enabled so\n    // existing users are not broken upon upgrade (#1250).\n    if (enabled === false && profileConfig(ctx)?.enabled === undefined && store.list().length > 0) {\n      enabled = true\n    }\n    return {\n      announceToAgent: readConfigField(config?.announceToAgent, DEFAULT_ANNOUNCE),\n      enabled,\n    }\n  }\n\n  // The /api/dsh-ssh route family + terminal upgrade.\n  const { routes, upgrade, terminalSessions } = makeRoutes({ store, engine })\n  let disposeRoutes: (() => void) | undefined\n\n  // Agent tools + their prompt sections.\n  const tools = [\n    sshListTool(engine),\n    sshExecTool(engine),\n    sshUploadTool(engine),\n    sshDownloadTool(engine),\n    sshTunnelTool(engine),\n    sshClusterTool(engine),\n  ]\n  let disposeTools: (() => void) | undefined\n\n  // System-prompt announcement.\n  let disposeSection: (() => void) | undefined\n\n  // Register (or drop) every surface to match the resolved config. Each group\n  // is kept under one disposer: re-registering first tears the old one down\n  // so duplicate-name registrations never throw.\n  const sync = (): void => {\n    // A settings edit reaches this instance without a remount; apply the\n    // connection ceiling before re-deriving the surfaces so connections opened\n    // by the request that follows use the new value.\n    engine.setConnectTimeout(readConfigField(config?.connectTimeoutMs, DEFAULT_CONNECT_TIMEOUT_MS))\n    const value = resolve()\n    if (disposeSection !== undefined) {\n      disposeSection()\n      disposeSection = undefined\n    }\n    if (disposeRoutes !== undefined) {\n      disposeRoutes()\n      disposeRoutes = undefined\n    }\n    if (disposeTools !== undefined) {\n      disposeTools()\n      disposeTools = undefined\n    }\n    if (!value.enabled) return\n    if (value.announceToAgent) {\n      disposeSection = ctx.systemPrompt.section({\n        name: 'plugin:dsh-ssh',\n        order: SECTION_ORDER,\n        // The announcement names the ssh_* tools, so it renders only while at\n        // least one of them is reachable: a restriction that removes the tool\n        // surface must take the guidance with it, instead of telling the model\n        // to call tools this session cannot see.\n        text: visibleToolText(ctx.tools, SSH_TOOL_NAMES, SSH_GUIDANCE),\n      })\n    }\n    disposeRoutes = ctx.effect(\n      () => {\n        const disposers = routes.map(route => ctx.webServer.register(route))\n        const upgradeDisposer = ctx.webServer.registerUpgrade(upgrade)\n        return () => {\n          for (const dispose of disposers) dispose()\n          upgradeDisposer()\n          // Dropping the routes also ends the terminal sessions they served:\n          // a live shell must not outlive the surface that can reach it.\n          terminalSessions.dispose()\n        }\n      },\n      'dsh-ssh: routes',\n    )\n    disposeTools = ctx.effect(\n      () => {\n        const disposers = tools.map(tool => ctx.tools.register(tool))\n        return () => { for (const dispose of disposers) dispose() }\n      },\n      'dsh-ssh: tools',\n    )\n  }\n\n  // A settings edit is committed into this instance's config references and\n  // announced on the owning fiber (the entry is not remounted), so the\n  // surfaces are re-derived from the new values here.\n  ctx.on('loader/volatile-update', () => { sync() })\n\n  // Initial registration from the config the Host activated this row with.\n  sync()\n}\n"
    },
    {
      "path": "packages/dsh-ssh/src/routes.ts",
      "content": "/**\n * The /api/dsh-ssh route family: host CRUD, exec, cluster, SFTP transfer\n * (NDJSON progress stream for uploads, binary stream for downloads), remote\n * listing, tunnels, and the WebSocket PTY terminal upgrade. Every route\n * carries a loopback-only trust fence (plus browser same-origin markers) —\n * these endpoints execute commands on remote servers, so LAN-exposed dsh web\n * deployments must not serve them.\n */\n\nimport { closeSync, createReadStream, createWriteStream, mkdirSync, openSync } from 'node:fs'\nimport { unlink } from 'node:fs/promises'\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport { basename, join } from 'node:path'\nimport { tmpdir } from 'node:os'\nimport { randomBytes } from 'node:crypto'\nimport { WebSocket, WebSocketServer } from 'ws'\nimport type { WebRoute, WebUpgradeRoute } from '@deepseek-ai/dsh-host-webserver'\nimport type { SshEngine } from './engine.ts'\nimport { TerminalSessionRegistry } from './engine/terminal-sessions.ts'\nimport { readJsonBody, writeJson } from './http.ts'\nimport { isLoopbackRequest } from './loopback.ts'\nimport { SSH_API, type HostPayload, type TerminalServerFrame } from './protocol.ts'\nimport type { HostStore } from './store.ts'\n\n/** Cap on declared upload bodies (staged to disk before SFTP). */\nconst MAX_UPLOAD_BYTES = 4 * 1024 * 1024 * 1024\n\n/**\n * One noServer WebSocket server for terminal upgrades: the browser half uses\n * a standards-compliant WebSocket, so the host must speak real RFC 6455\n * frames (the webserver hands us the raw upgraded socket).\n */\nconst terminalWss = new WebSocketServer({ noServer: true })\n\n/** URL query helper (first value, decoded). */\nfunction queryParam(url: URL, name: string): string | undefined {\n  const value = url.searchParams.get(name)\n  return value === null ? undefined : value\n}\n\n/** Route family dependencies. */\nexport interface SshRoutesDeps {\n  /** The host store (CRUD). */\n  store: HostStore\n  /** The engine (ops). */\n  engine: SshEngine\n  /** Temp dir for upload/download staging (tests inject a sandbox). */\n  stagingDir?: string\n/** Upload byte cap override (tests); defaults to MAX_UPLOAD_BYTES. */\nmaxUploadBytes?: number\n}\n\n/**\n * Build every /api/dsh-ssh route (exact paths) plus the terminal upgrade.\n * @param deps - store, engine, staging dir.\n * @returns routes and the upgrade route.\n */\nexport function makeRoutes(deps: SshRoutesDeps): { routes: WebRoute[]; upgrade: WebUpgradeRoute; terminalSessions: TerminalSessionRegistry } {\n  const { store, engine } = deps\n  const staging = deps.stagingDir ?? join(tmpdir(), 'dsh-ssh-uploads')\nconst maxUploadBytes = deps.maxUploadBytes ?? MAX_UPLOAD_BYTES\n  // The upload route stages request bodies here; it must exist before the\n  // first request (a missing dir would hang the first upload forever).\n  // 0700 keeps in-flight transfers unreadable to other local users (the\n  // staged files below are 0600; downloads are pre-created 0600 as well).\n  mkdirSync(staging, { recursive: true, mode: 0o700 })\n\n  /** Guard helper: fence + method check. */\n  const guard = (req: IncomingMessage, res: ServerResponse, method: string): boolean => {\n    if (!isLoopbackRequest(req)) {\n      writeJson(res, 403, { error: 'forbidden: loopback-only' })\n      return false\n    }\n    if (req.method !== method) {\n      writeJson(res, 405, { error: `method not allowed: ${req.method}` })\n      return false\n    }\n    return true\n  }\n\n  const routes: WebRoute[] = [\n    // ------------------------------------------------------------ hosts\n    {\n      kind: 'exact',\n      path: SSH_API.hosts,\n      handler: async (req, res) => {\n        // One handler per path (the webserver keyed route registry rejects\n        // duplicate (kind, path)); dispatch by HTTP method here.\n        const method = req.method ?? 'GET'\n        if (!isLoopbackRequest(req)) {\n          writeJson(res, 403, { error: 'forbidden: loopback-only' })\n          return\n        }\n        const url = new URL(req.url ?? '/', 'http://localhost')\n        if (method === 'GET') {\n          writeJson(res, 200, { hosts: engine.list(queryParam(url, 'query')) })\n          return\n        }\n        if (method === 'POST') {\n          const body = (await readJsonBody(req)) as Record<string, unknown> | null\n          if (body === null) {\n            writeJson(res, 400, { error: 'invalid JSON body' })\n            return\n          }\n          try {\n            const entry = store.create(body as unknown as HostPayload)\n            writeJson(res, 201, { host: store.summarize(entry) })\n          } catch (error) {\n            writeJson(res, 400, { error: error instanceof Error ? error.message : String(error) })\n          }\n          return\n        }\n        if (method !== 'PATCH' && method !== 'DELETE') {\n          writeJson(res, 405, { error: `method not allowed: ${method}` })\n          return\n        }\n        const alias = queryParam(url, 'alias')\n        if (alias === undefined || alias === '') {\n          writeJson(res, 400, { error: 'alias query parameter is required' })\n          return\n        }\n        if (method === 'PATCH') {\n          const body = (await readJsonBody(req)) as Record<string, unknown> | null\n          if (body === null) {\n            writeJson(res, 400, { error: 'invalid JSON body' })\n            return\n          }\n          try {\n            const entry = store.update(alias, body as unknown as Partial<HostPayload>)\n            // Connection-relevant changes invalidate the pooled connection:\n            // without this the pool would keep running commands on the old\n            // host/credentials until the idle sweep (up to 30 min later).\n            // Agent forwarding belongs here too: it is fixed per connection\n            // (ssh2 negotiates it when the channel opens), so toggling it must\n            // reconnect or the new setting silently never takes effect.\n            const patch = body as Record<string, unknown>\n            if (['host', 'port', 'user', 'auth', 'proxyJump', 'proxyCommand', 'forwardAgent'].some(key => patch[key] !== undefined)) {\n              engine.dropAlias(alias)\n            }\n            writeJson(res, 200, { host: store.summarize(entry) })\n          } catch (error) {\n            writeJson(res, 400, { error: error instanceof Error ? error.message : String(error) })\n          }\n          return\n        }\n        if (method === 'DELETE') {\n          try {\n            engine.dropAlias(alias)\n            store.delete(alias)\n            writeJson(res, 200, { ok: true })\n          } catch (error) {\n            writeJson(res, 400, { error: error instanceof Error ? error.message : String(error) })\n          }\n          return\n        }\n        writeJson(res, 405, { error: `method not allowed: ${method}` })\n      },\n    },\n    {\n      kind: 'exact',\n      path: SSH_API.importSshConfig,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'POST')) return\n        try {\n          writeJson(res, 200, { result: store.importFromSshConfig() })\n        } catch (error) {\n          writeJson(res, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n    // ------------------------------------------------------------ ops\n    {\n      kind: 'exact',\n      path: SSH_API.test,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'POST')) return\n        const body = (await readJsonBody(req)) as Record<string, unknown> | null\n        const alias = typeof body?.alias === 'string' ? body.alias : ''\n        if (alias === '') {\n          writeJson(res, 400, { error: 'alias is required' })\n          return\n        }\n        try {\n          writeJson(res, 200, { result: await engine.test(alias) })\n        } catch (error) {\n          writeJson(res, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: SSH_API.exec,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'POST')) return\n        const body = (await readJsonBody(req)) as Record<string, unknown> | null\n        const alias = typeof body?.alias === 'string' ? body.alias : ''\n        const command = typeof body?.command === 'string' ? body.command : ''\n        if (alias === '' || command === '') {\n          writeJson(res, 400, { error: 'alias and command are required' })\n          return\n        }\n        const timeoutMs = typeof body?.timeoutMs === 'number' ? body.timeoutMs : undefined\n        try {\n          writeJson(res, 200, { result: await engine.exec(alias, command, timeoutMs) })\n        } catch (error) {\n          writeJson(res, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n    {\n      kind: 'exact',\n      path: SSH_API.cluster,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'POST')) return\n        const body = (await readJsonBody(req)) as Record<string, unknown> | null\n        const command = typeof body?.command === 'string' ? body.command : ''\n        if (command === '') {\n          writeJson(res, 400, { error: 'command is required' })\n          return\n        }\n        const aliases = Array.isArray(body?.aliases) ? body.aliases.filter((x): x is string => typeof x === 'string') : undefined\n        const tags = Array.isArray(body?.tags) ? body.tags.filter((x): x is string => typeof x === 'string') : undefined\n        const environment = typeof body?.environment === 'string' ? body.environment : undefined\n        const timeoutMs = typeof body?.timeoutMs === 'number' ? body.timeoutMs : undefined\n        const maxWorkers = typeof body?.maxWorkers === 'number' ? body.maxWorkers : undefined\n        const hasAliases = aliases?.some(alias => alias.trim() !== '') === true\n        const hasEnvironment = typeof environment === 'string' && environment.trim() !== ''\n        const hasTags = tags?.some(tag => tag.trim() !== '') === true\n        if (!hasAliases && !hasEnvironment && !hasTags) {\n          writeJson(res, 400, { error: 'ssh_cluster requires aliases, environment, or tags to limit the target set' })\n          return\n        }\n        try {\n          writeJson(res, 200, { results: await engine.cluster({ command, aliases, environment, tags, timeoutMs, maxWorkers }) })\n        } catch (error) {\n          writeJson(res, 500, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n    // ------------------------------------------------------------- ls\n    {\n      kind: 'exact',\n      path: SSH_API.ls,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'GET')) return\n        const url = new URL(req.url ?? '/', 'http://localhost')\n        const alias = queryParam(url, 'alias')\n        const path = queryParam(url, 'path') ?? '/'\n        if (alias === undefined || alias === '') {\n          writeJson(res, 400, { error: 'alias query parameter is required' })\n          return\n        }\n        try {\n          writeJson(res, 200, { entries: await engine.ls(alias, path) })\n        } catch (error) {\n          writeJson(res, 400, { error: error instanceof Error ? error.message : String(error) })\n        }\n      },\n    },\n    // --------------------------------------------------------- tunnel\n    {\n      kind: 'exact',\n      path: SSH_API.tunnel,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'POST')) return\n        const body = (await readJsonBody(req)) as Record<string, unknown> | null\n        const action = typeof body?.action === 'string' ? body.action : ''\n        if (action === 'list') {\n          writeJson(res, 200, { tunnels: engine.listTunnels() })\n          return\n        }\n        if (action === 'start') {\n          const alias = typeof body?.alias === 'string' ? body.alias : ''\n          const remotePort = typeof body?.remotePort === 'number' ? body.remotePort : undefined\n          if (alias === '' || remotePort === undefined) {\n            writeJson(res, 400, { error: 'alias and remotePort are required' })\n            return\n          }\n          try {\n            const tunnel = await engine.startTunnel(alias, {\n              remotePort,\n              remoteHost: typeof body?.remoteHost === 'string' && body.remoteHost !== '' ? body.remoteHost : undefined,\n              localPort: typeof body?.localPort === 'number' ? body.localPort : undefined,\n            })\n            writeJson(res, 200, { tunnel })\n          } catch (error) {\n            writeJson(res, 500, { error: error instanceof Error ? error.message : String(error) })\n          }\n          return\n        }\n        if (action === 'stop') {\n          const id = typeof body?.tunnelId === 'string' ? body.tunnelId : ''\n          if (id === '') {\n            writeJson(res, 400, { error: 'tunnelId is required' })\n            return\n          }\n          writeJson(res, 200, { ok: engine.stopTunnel(id) })\n          return\n        }\n        if (action === 'stop-all') {\n          const alias = typeof body?.alias === 'string' ? body.alias : undefined\n          writeJson(res, 200, { stopped: engine.stopAllTunnels(alias === '' ? undefined : alias) })\n          return\n        }\n        writeJson(res, 400, { error: `unknown action '${action}'` })\n      },\n    },\n    // --------------------------------------------------------- upload\n    {\n      kind: 'exact',\n      path: SSH_API.upload,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'POST')) return\n        const url = new URL(req.url ?? '/', 'http://localhost')\n        const alias = queryParam(url, 'alias')\n        const remotePath = queryParam(url, 'remotePath')\n        if (alias === undefined || remotePath === undefined) {\n          writeJson(res, 400, { error: 'alias and remotePath query parameters are required' })\n          return\n        }\n        const declared = Number(req.headers['content-length'])\n        if (Number.isFinite(declared) && declared > maxUploadBytes) {\n          writeJson(res, 413, { error: 'upload body too large' })\n          return\n        }\n        res.writeHead(200, {\n          'content-type': 'application/x-ndjson; charset=utf-8',\n          'cache-control': 'no-cache',\n          'referrer-policy': 'no-referrer',\n        })\n        const emit = (line: unknown): void => {\n          try { res.write(JSON.stringify(line) + '\\n') } catch { /* client gone */ }\n        }\n        // Stage the uploaded bytes, then SFTP them out with progress frames.\n        const tmp = join(staging, `upload-${randomBytes(6).toString('hex')}`)\n        const sink = createWriteStream(tmp, { mode: 0o600 })\n        let settled = false\n        // Every terminal path (sink error, client abort, response loss) must\n        // emit a result frame, end the response, and remove the tmp file.\n        const fail = (error: unknown): void => {\n          if (settled) return\n          settled = true\n          emit({ type: 'result', ok: false, error: error instanceof Error ? error.message : String(error) })\n          // End the response only after the tmp file is gone, and unlink only\n          // after the sink is fully closed: destroying a WriteStream whose\n          // fs.open is still pending lets the open RE-CREATE the file after\n          // an early unlink, leaving staging populated (this raced the\n          // response end and made the byte-cap test flaky).\n          const cleanup = (): void => {\n            void unlink(tmp).catch(() => undefined).finally(() => {\n              try { res.end() } catch { /* closed */ }\n            })\n          }\n          if (sink.destroyed) {\n            cleanup()\n          } else {\n            sink.once('close', cleanup)\n            try { sink.destroy() } catch { cleanup() }\n          }\n        }\n        const done = (): void => {\n          if (settled) return\n          settled = true\n          try { res.end() } catch { /* closed */ }\n        }\n        sink.on('error', (error) => fail(error))\n        req.on('error', (error) => fail(error))\n        req.on('aborted', () => fail('upload aborted by the client'))\n        res.on('error', () => fail('response stream closed'))\n        res.on('close', () => { if (!res.writableEnded) fail('connection closed') })\n        // The content-length pre-check above can be bypassed by chunked or\n        // header-less requests: count the bytes as they actually arrive and\n        // abort the moment the cap is exceeded.\n        let received = 0\n        let capped = false\n        req.on('data', (chunk: Buffer) => {\n          received += chunk.byteLength\n          if (received > maxUploadBytes && !capped) {\n            capped = true\n            fail('upload body too large')\n            // Keep the socket alive until the response flush finishes:\n            // destroying the request here races res.end() and the client\n            // sees a hang-up instead of the result frame. Drain the rest of\n            // the body so the socket can close cleanly afterwards.\n            res.on('finish', () => { try { req.destroy() } catch { /* closed */ } })\n            req.resume()\n          }\n        })\n        req.pipe(sink)\n        sink.on('finish', async () => {\n          if (settled) return\n          emit({ type: 'progress', progress: { phase: 'connecting', file: remotePath, transferred: 0, total: 0, percent: 0 } })\n          try {\n            const outcome = await engine.upload(alias, tmp, remotePath, false, progress => emit({ type: 'progress', progress }))\n            emit({ type: 'result', ok: true, transferredBytes: outcome.bytes })\n          } catch (error) {\n            emit({ type: 'result', ok: false, error: error instanceof Error ? error.message : String(error) })\n          } finally {\n            await unlink(tmp).catch(() => undefined)\n            done()\n          }\n        })\n      },\n    },\n    // ------------------------------------------------------- download\n    {\n      kind: 'exact',\n      path: SSH_API.download,\n      handler: async (req, res) => {\n        if (!guard(req, res, 'GET')) return\n        const url = new URL(req.url ?? '/', 'http://localhost')\n        const alias = queryParam(url, 'alias')\n        const remotePath = queryParam(url, 'remotePath')\n        if (alias === undefined || remotePath === undefined) {\n          writeJson(res, 400, { error: 'alias and remotePath query parameters are required' })\n          return\n        }\n        const tmp = join(staging, `download-${randomBytes(6).toString('hex')}`)\n        try {\n          // Pre-create with 0600: ssh2's fastGet opens the destination with\n          // umask-default permissions and a pre-created file keeps the mode.\n          closeSync(openSync(tmp, 'w', 0o600))\n          const outcome = await engine.download(alias, remotePath, tmp)\n          res.writeHead(200, {\n            'content-type': 'application/octet-stream',\n            'content-length': String(outcome.bytes),\n            'content-disposition': `attachment; filename=\"${basename(remotePath).replace(/\"/g, '')}\"`,\n            'referrer-policy': 'no-referrer',\n          })\n          await new Promise<void>((resolve, reject) => {\n            const source = createReadStream(tmp)\n            source.on('error', reject)\n            res.on('error', reject)\n            source.pipe(res)\n            source.on('end', resolve)\n          })\n        } catch (error) {\n          if (!res.headersSent) {\n            writeJson(res, 400, { error: error instanceof Error ? error.message : String(error) })\n          } else {\n            // Mid-stream failure after headers: destroy so the browser does\n            // not hang waiting for the