d' }\n          try { ws.send(JSON.stringify(expired)) } catch { /* socket raced away */ }\n          try { ws.close(1000) } catch { /* already closed */ }\n          return\n        }\n        void terminalSessions.open(ws, alias as string, size)\n      })\n    },\n  }\n\n  return { routes, upgrade, terminalSessions }\n}\n"
